function Shell({ page, setPage, children, openCommand, session }:{ page:Page; setPage:(p:Page)=>void; children:React.ReactNode; openCommand:()=>void;session:Session }) {
  const initials=session.user.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();
  return <main className="app-shell">
    <header className="topbar">
      <button className="brand" onClick={()=>setPage('Overview')}><img src="/scout-logo.png" alt="" /><span>SCOUT</span></button>
      <div className="workspace-name">{session.workspace.name} <FiChevronDown /></div>
      <div className="top-actions"><button className="search" onClick={openCommand}><FiSearch /> Search <kbd>⌘ K</kbd></button><button className="icon-button" aria-label="Notifications"><FiBell /></button><button className="avatar" onClick={()=>setPage('Settings')} aria-label={`Account: ${session.user.name}`}>{initials}</button></div>
    </header>
    <div className="subbar"><div className="sub-context"><span>Sales</span><strong>{page}</strong></div><div className="sub-actions"><button onClick={openCommand}><FiSearch /> Search this view</button><button aria-label="More page actions"><FiMoreHorizontal /></button></div></div>
    {children}
  </main>
}

