  const taskCount=(item:string)=>item==='Completed'?tasks.filter(task=>task.status==='Completed').length:tasks.filter(task=>task.status!=='Completed'&&(item==='Today'?task.due==='Today':item==='Overdue'?task.due==='Overdue':!['Today','Overdue'].includes(task.due))).length;
