  useEffect(()=>setActivityPage(1),[mode,scope,type,owner,lead,period,query]);
  const activityToForm=(activity:ActivityEntry):ActivityFormState=>({type:activity.type,lead:activity.lead,owner:activity.owner,detail:activity.detail,status:activity.status||'Completed',occurredAt:activity.occurredAt||localDateTime(),outcome:activity.outcome||outcomeOptions(activity.type)[0],duration:activity.duration||'',subject:activity.subject||'',value:activity.value||'',documentLink:activity.documentLink||'',relatedTask:activity.relatedTaskId?`${activity.relatedTaskId} · ${taskLabel(activity.relatedTaskId)}`:'No related task',opportunity:activity.opportunity||'No opportunity',attachmentKey:activity.attachmentKey||'',attachmentName:activity.attachmentName||''});
