  const [mode,setMode]=useState<'Timeline'|'List'>('Timeline');const [scope,setScope]=useState<'Completed'|'Scheduled'|'Deleted'>('Completed');const [type,setType]=useState('All activity');const [owner,setOwner]=useState('Entire team');const [lead,setLead]=useState('All leads');const [period,setPeriod]=useState('All time');const [range,setRange]=useState({from:'',to:''});const [query,setQuery]=useState('');const [page,setActivityPage]=useState(1);const [filtersReady,setFiltersReady]=useState(false);const [creating,setCreating]=useState(false);const [selectedId,setSelectedId]=useState<number|null>(null);const [deleting,setDeleting]=useState<number|null>(null);const [hardDeleting,setHardDeleting]=useState<number|null>(null);const [lastDeletedId,setLastDeletedId]=useState<number|null>(null);const [busy,setBusy]=useState(false);const [file,setFile]=useState<File|null>(null);const [removeAttachment,setRemoveAttachment]=useState(false);const [form,setForm]=useState<ActivityFormState>(emptyForm);const [editForm,setEditForm]=useState<ActivityFormState>(emptyForm);const [remotePage,setRemotePage]=useState<{activities:ActivityEntry[];total:number}|null>(null);const selected=activities.find(activity=>activity.id===selectedId)||null;
  const outcomeOptions=(activityType:string)=>activityType==='Call'?['Connected','No answer','Voicemail','Rescheduled','Not interested']:activityType==='Email'?['Sent','Replied','Bounced','Follow-up required']:activityType==='Meeting'?['Completed','Rescheduled','Cancelled','Follow-up required']:activityType==='Proposal'?['Sent','Viewed','Accepted','Changes requested','Declined']:['Noted'];
  const activityDate=(activity:ActivityEntry)=>{const parsed=new Date(activity.occurredAt||'');return Number.isNaN(parsed.getTime())?new Date(activity.id):parsed};
  const dayKey=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
  const friendlyTime=(value:string,status:ActivityFormState['status'])=>{const date=new Date(value);if(Number.isNaN(date.getTime()))return status==='Scheduled'?'Scheduled':'Just now';const today=new Date();const label=dayKey(date)===dayKey(today)?'Today':date.toLocaleDateString('en-US',{month:'short',day:'numeric'});return `${label} · ${date.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',hour12:false})}`};
  const groupLabel=(activity:ActivityEntry)=>{const date=activityDate(activity);const today=new Date();const yesterday=new Date(today);yesterday.setDate(today.getDate()-1);if(dayKey(date)===dayKey(today))return 'Today';if(dayKey(date)===dayKey(yesterday))return 'Yesterday';return date.toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',year:date.getFullYear()===today.getFullYear()?undefined:'numeric'})};
  const shortTime=(activity:ActivityEntry)=>activityDate(activity).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',hour12:false});
  const taskLabel=(id?:number)=>id?tasks.find(task=>task.id===id)?.title:'';const relatedTaskOptions=['No related task',...tasks.map(task=>`${task.id} · ${task.title}`)];
  const matchesPeriod=(activity:ActivityEntry)=>{if(period==='All time')return true;const date=activityDate(activity);const today=new Date();if(period==='Today')return dayKey(date)===dayKey(today);if(period==='This week'){const start=new Date(today);start.setHours(0,0,0,0);start.setDate(today.getDate()-((today.getDay()+6)%7));const end=new Date(start);end.setDate(start.getDate()+7);return date>=start&&date<end}if(period==='This month')return date.getFullYear()===today.getFullYear()&&date.getMonth()===today.getMonth();if(period==='Custom range'){const key=dayKey(date);return (!range.from||key>=range.from)&&(!range.to||key<=range.to)}return true};
  const matchesScope=(activity:ActivityEntry)=>scope==='Deleted'?!!activity.deletedAt:!activity.deletedAt&&(scope==='Scheduled'?activity.status==='Scheduled':activity.status!=='Scheduled');
  const localVisible=activities.filter(activity=>matchesScope(activity)&&(type==='All activity'||activity.type===type)&&(owner==='Entire team'||activity.owner===owner)&&(lead==='All leads'||activity.lead===lead)&&matchesPeriod(activity)&&(activity.lead+activity.detail+(activity.subject||'')+(activity.outcome||'')).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>activityDate(scope==='Scheduled'?a:b).getTime()-activityDate(scope==='Scheduled'?b:a).getTime());
