  const activityToForm=(activity:ActivityEntry):ActivityFormState=>({type:activity.type,lead:activity.lead,owner:activity.owner,detail:activity.detail,status:activity.status||'Completed',occurredAt:activity.occurredAt||localDateTime(),outcome:activity.outcome||outcomeOptions(activity.type)[0],duration:activity.duration||'',subject:activity.subject||'',value:activity.value||'',documentLink:activity.documentLink||'',relatedTask:activity.relatedTaskId?`${activity.relatedTaskId} · ${taskLabel(activity.relatedTaskId)}`:'No related task',opportunity:activity.opportunity||'No opportunity',attachmentKey:activity.attachmentKey||'',attachmentName:activity.attachmentName||''});
  const openActivity=(activity:ActivityEntry)=>{setSelectedId(activity.id);setEditForm(activityToForm(activity));setFile(null);setRemoveAttachment(false)};
  const validDocument=(value:string)=>{if(!value)return true;try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)}catch{return false}};
  const uploadAttachment=async()=>{if(!file)return null;const data=new FormData();data.append('file',file);const response=await fetch('/api/activity-files',{method:'POST',body:data});if(!response.ok)throw new Error('Upload failed');return response.json() as Promise<{key:string;name:string}>};
  const deleteAttachment=async(key?:string)=>{if(key)await fetch(`/api/activity-files?key=${encodeURIComponent(key)}`,{method:'DELETE'})};
  const parseTaskId=(value:string)=>value==='No related task'?undefined:Number(value.split(' · ')[0]);
  const taskDue=(value:string)=>{const date=new Date(value);const today=new Date();const tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);if(dayKey(date)===dayKey(today))return 'Today';if(dayKey(date)===dayKey(tomorrow))return 'Tomorrow';return date.toLocaleDateString('en-US',{month:'short',day:'numeric'})};
  const syncScheduledTask=(state:ActivityFormState,activityId:number)=>{let taskId=parseTaskId(state.relatedTask);if(state.status!=='Scheduled')return taskId;taskId=taskId||activityId+1;const linked:TaskItem={id:taskId,title:`${state.type}: ${state.detail.trim()}`,lead:state.lead,owner:state.owner,priority:'Medium',due:taskDue(state.occurredAt),time:state.occurredAt.slice(11,16)||'09:00',type:state.type==='Call'?'Callback':state.type,notes:'Scheduled from Activities.',status:'Scheduled',reminder:'15 minutes before',recurrence:'None'};setTasks(value=>value.some(task=>task.id===taskId)?value.map(task=>task.id===taskId?{...task,...linked}:task):[linked,...value]);return taskId};
  const toEntry=(state:ActivityFormState,id:number,attachment?:{key:string;name:string}|null,taskId?:number):ActivityEntry=>({id,lead:state.lead,type:state.type,detail:state.detail.trim(),time:friendlyTime(state.occurredAt,state.status),owner:state.owner,status:state.status,occurredAt:state.occurredAt,outcome:state.outcome,duration:state.duration,subject:state.subject,value:state.value,documentLink:state.documentLink||undefined,attachmentKey:attachment?.key||state.attachmentKey||undefined,attachmentName:attachment?.name||state.attachmentName||undefined,relatedTaskId:taskId??parseTaskId(state.relatedTask),opportunity:state.opportunity==='No opportunity'?undefined:state.opportunity});
  const addActivity=async()=>{if(!form.detail.trim()||busy)return;if(!validDocument(form.documentLink)){notify('Use a valid http or https document link');return}setBusy(true);try{const id=Date.now();const attachment=await uploadAttachment();const taskId=syncScheduledTask(form,id);setActivities(value=>[toEntry(form,id,attachment,taskId),...value]);setCreating(false);setFile(null);setForm(emptyForm());notify(form.status==='Scheduled'?'Activity scheduled with a task reminder':'Activity logged')}catch{notify('Attachment upload failed')}finally{setBusy(false)}};
  const saveActivity=async()=>{if(!selected||!editForm.detail.trim()||busy)return;if(!validDocument(editForm.documentLink)){notify('Use a valid http or https document link');return}setBusy(true);try{const attachment=await uploadAttachment();if((removeAttachment||attachment)&&selected.attachmentKey)await deleteAttachment(selected.attachmentKey);const adjusted=removeAttachment?{...editForm,attachmentKey:'',attachmentName:''}:editForm;const taskId=syncScheduledTask(adjusted,selected.id);if(selected.status==='Scheduled'&&adjusted.status==='Completed'&&selected.relatedTaskId)setTasks(value=>value.map(task=>task.id===selected.relatedTaskId?{...task,status:'Completed'}:task));setActivities(value=>value.map(activity=>activity.id===selected.id?{...activity,...toEntry(adjusted,selected.id,attachment,taskId),deletedAt:activity.deletedAt}:activity));setSelectedId(null);setFile(null);setRemoveAttachment(false);notify('Activity updated')}catch{notify('Activity could not be saved')}finally{setBusy(false)}};
  const createFollowup=(activity:ActivityEntry)=>{const id=Date.now();setTasks(value=>[{id,title:`Follow up: ${activity.detail}`,lead:activity.lead,owner:activity.owner,priority:'Medium',due:'Tomorrow',time:'09:00',type:activity.type==='Email'?'Email':'Callback',notes:`Created from ${activity.type.toLowerCase()} activity.`,status:'Scheduled',reminder:'15 minutes before',recurrence:'None'},...value]);setActivities(value=>value.map(item=>item.id===activity.id?{...item,relatedTaskId:id}:item));notify('Follow-up task created')};
